package.manifest_json:
{
  "format": 1,
  "id": "module-self-diagnosis",
  "version": 3,
  "purpose": "When a module reports that its findings changed, read its diagnostics.findings and wake the agent that owns the module only when a finding is new, got more severe, or has grown by half (and by at least three), at most once per four hours. A six-hour timer runs the same check in case a report is missed. A finding that vanishes and returns within six hours is not new. Info findings are recorded but never wake. A module that does not answer is itself reported.",
  "explanation": "This flow reads the health findings of one CortexKit module, chosen when the flow is set up, whenever that module reports that its findings changed, and every six hours in case a report is missed. It wakes the agent that owns that module only when a finding is new, gets worse, or grows by half, and at most once in four hours for the same finding. It reads the findings and writes nothing. It exists so that a module's owner learns about slow queries, stuck work or errors without checking by hand.",
  "changes": "This version runs when the module reports changed findings, instead of every 15 minutes, with a six-hour timer as a backup. Only modules that publish that report can be chosen; today that is synapse.",
  "trigger": {
    "events": [{ "module": "$params.module", "name": "findings_changed", "version": 1 }],
    "schedule": { "interval": "6h", "missed": "once" }
  },
  "ops": [
    { "module": "$params.module", "op": "events_get" },
    { "module": "$params.module", "op": "diagnostics.findings" }
  ],
  "sinks": [{ "agent": "$self", "digest_max": "wake" }],
  "deadline": "2m",
  "params": {
    "module": { "type": "enum", "values": ["synapse"] }
  },
  "template": { "max_per_agent": 10, "max_lifetime": "365d" }
}

package.script:
// Wake the agent that owns a module when the module's self-diagnosis reports a
// finding that is new since the last report, or has grown (a larger count or a
// worse severity). Unchanged findings stay quiet. A finding whose count keeps
// growing wakes again at most once per quiet period; a worse severity always
// wakes. The last reported state lives in kv under REPORTED.
//
// Both event and schedule runs read the chosen module's current findings.
// Elapsed time, not the number of runs, bounds quiet and vanished windows:
// events can arrive in bursts and the backup timer runs only every six hours.

const REPORTED = 'reported';
const BODY_MAX = 4000;
const DATA_MAX = 8000;
const SEVERITY_RANK = { warn: 1, warning: 1, error: 2 };
const QUIET_MS = 4 * 60 * 60 * 1000;
const GONE_MS = 6 * 60 * 60 * 1000;
const now = Date.now();

// A count is worse when it has grown by at least half and by at least three,
// so small drifts in rolling-window counts stay quiet.
function grewEnough(before, now) {
  return now - before >= 3 && now >= before * 1.5;
}

function utf8Length(text) {
  return encodeURIComponent(text).replace(/%[A-F\d]{2}/g, 'x').length;
}

function clip(text, max) {
  const value = String(text ?? '');
  return value.length > max ? value.slice(0, max - 1) + '…' : value;
}

const moduleId = params.module;
const replaceKey = `module-self-diagnosis-${moduleId}`;

// A call that fails is itself a finding, so a module that stops answering is
// reported like any other problem.
let findings;
try {
  const reply = await ops.call(moduleId, 'diagnostics.findings', {});
  findings = reply.findings ?? [];
} catch (error) {
  const code = error?.data?.code ?? 'call_failed';
  findings = [{
    check: 'diagnostics_unreachable',
    key: 'diagnostics_unreachable',
    severity: 'error',
    count: 1,
    summary: `${moduleId} did not answer diagnostics.findings (${code})`,
    hint: clip(error?.message ?? String(error), 300),
    samples: [],
  }];
}

// A module can report the same check more than once in one reply. Keep only
// the worst per id, so one run never writes two states for the same id and the
// later one silently overwrites the earlier.
const rankOf = (finding) => SEVERITY_RANK[finding.severity] ?? 0;
const worstById = new Map();
for (const finding of findings) {
  const id = finding.key ?? finding.check;
  const held = worstById.get(id);
  if (
    !held ||
    rankOf(finding) > rankOf(held) ||
    (rankOf(finding) === rankOf(held) && Number(finding.count ?? 0) > Number(held.count ?? 0))
  ) {
    worstById.set(id, finding);
  }
}
const current = [...worstById.entries()];
const reported = (await kv.get(REPORTED)) ?? {};
const next = {};
const changed = [];
for (const [id, finding] of current) {
  const count = Number(finding.count ?? 0);
  const rank = rankOf(finding);
  const before = reported[id]?.gone_until <= now ? undefined : reported[id];
  const quiet_until = before?.quiet_until ?? 0;
  const quiet = quiet_until > now;
  // Info findings (and any severity this flow doesn't rank) are recorded but
  // never wake: they describe data quality or bookkeeping, not a failure.
  if (rank === 0) {
    next[id] = { count, rank, quiet_until };
    continue;
  }
  if (!before) {
    changed.push({ label: 'NEW', finding });
    next[id] = { count, rank, quiet_until: now + QUIET_MS, peak: rank };
    continue;
  }
  // During the quiet period, a severity that eases and returns to a level
  // already reported is not worse: only a rank above that peak wakes. This
  // stops a finding that alternates between warn and error from paging every run.
  const peak = quiet ? Math.max(before.peak ?? before.rank, before.rank) : before.rank;
  if (rank > peak || (grewEnough(before.count, count) && !quiet)) {
    changed.push({ label: 'WORSE', finding, before });
    next[id] = { count, rank, quiet_until: now + QUIET_MS, peak: rank };
    continue;
  }
  // Keep the reported baseline while a count drifts inside the threshold, or
  // grows during the quiet period, so the next report measures all the growth
  // since the last one. A finding that shrinks or eases resets the baseline, so
  // a later regrowth is measured from the lower point.
  const keep = count >= before.count && rank === before.rank;
  const keptPeak = quiet ? peak : rank;
  next[id] = keep
    ? { count: before.count, rank: before.rank, quiet_until, peak: keptPeak }
    : { count, rank, quiet_until, peak: keptPeak };
}
// Remember a vanished finding for six hours from its first absent report.
// Returning findings are compared with the last report until that deadline,
// even if many events arrive in the meantime.
for (const [id, before] of Object.entries(reported)) {
  if (next[id]) continue;
  const gone_until = before.gone_until ?? now + GONE_MS;
  if (gone_until > now) next[id] = { ...before, gone_until };
}
await kv.set(REPORTED, next);

if (changed.length === 0) {
  if (current.length === 0 && Object.keys(reported).some((id) => !reported[id].gone_until)) {
    // Everything cleared: drop an alert that has not been read yet.
    await sink.digest.withdraw(self.agent_id, { replace_key: replaceKey });
  }
  return;
}

const lines = [];
for (const { label, finding, before } of changed) {
  const was = before ? ` (was ${before.count})` : '';
  lines.push(`${label} ${finding.check}: ${finding.severity}, ${finding.count}${was}. ${clip(finding.summary, 300)}`);
  lines.push(`  next: ${clip(finding.hint, 400)}`);
}
const unchanged = current.length - changed.length;
if (unchanged > 0) {
  lines.push(`${unchanged} other finding(s) unchanged since the last report.`);
}
let body = lines.join('\n');
while (utf8Length(body) > BODY_MAX && lines.length > 1) {
  lines.splice(lines.length - 2, 1);
  body = lines.join('\n') + '\n(more in data)';
}

// Samples carry the ids to act on; keep as many as fit the data limit.
let perFinding = 3;
let data;
do {
  data = {
    module: moduleId,
    findings: changed.map(({ label, finding }) => ({
      label,
      check: finding.check,
      severity: finding.severity,
      count: finding.count,
      samples: (finding.samples ?? []).slice(0, perFinding),
    })),
  };
  perFinding -= 1;
} while (utf8Length(JSON.stringify(data)) > DATA_MAX && perFinding >= 0);
if (utf8Length(JSON.stringify(data)) > DATA_MAX) {
  data = { module: moduleId, findings: data.findings.map(({ samples, ...rest }) => rest) };
}

const worst = changed.some(({ finding }) => finding.severity === 'error') ? 'error' : 'warn';
await sink.digest(self.agent_id, {
  title: clip(`Self-diagnosis for ${moduleId}: ${changed.length} new or worse finding(s), worst ${worst}`, 200),
  body,
  data,
}, 'wake', { replace_key: replaceKey });
